const vpDamageTables={n23:[[1,1,'Persistent Rattle'],[2,2,'Handling Glitch'],[3,3,'Unreliable'],[4,4,'Loss of Power'],[5,5,'Damaged Bodywork'],[6,6,'Damaged Frame']],n26:[[11,11,'Lesson Learnt'],[12,12,'Eternal Enmity'],[13,13,'Bitter Enmity'],[14,14,'Personal Enmity'],[15,16,'Percussive Repair'],[21,26,'Superficial Damage'],[31,46,'Major Damage'],[51,52,'Busted Sights'],[53,53,'Drive System Fault'],[54,54,'Buckled Frame'],[55,56,'Engine Fracture'],[61,62,'Captured'],[63,65,'Critical Damage'],[66,66,'Catastrophic Explosion!']]};
const vpDamageRules=(edition=ed())=>(R().effects||[]).filter(x=>x.category==='lasting damages'&&x.edition===edition).map(x=>{const range=vpDamageTables[edition]?.find(r=>r[2]===vpName(x));return {...x,min:range?.[0],max:range?.[1]}}).sort((a,b)=>num(a.min)-num(b.min));
function vpModifiers(v,category){const sum={};const add=(key,value)=>sum[key]=(sum[key]||0)+num(value);if(category==='Damage')for(const damage of vpDamages(v))for(const m of damage.modifiers||[])add(m.stat_name,m.numeric_value??m.default_numeric_value);if(category==='Upgrades')for(const item of v.equipment||[])for(const effect of item.vehicleEffects||[])for(const m of effect.modifiers||[])if(!/_slots$/.test(m.stat_name))add(m.stat_name,m.numeric_value??m.default_numeric_value);if(category==='User')for(const [key,value]of Object.entries(v.userModifiers||{}))add(key,value);return sum}
function vpStats(v,pending={}){return Object.fromEntries(vpStatFields.map(([key])=>[key,num(v[key])+num(vpModifiers(v,'Damage')[key])+num(vpModifiers(v,'Upgrades')[key])+num(vpModifiers(v,'User')[key])+num(pending[key])]))}
function vpStatTable(v,pending={}){const current=vpStats(v,pending),rows=[['Base',Object.fromEntries(vpStatFields.map(([key])=>[key,num(v[key])]))],...['Damage','Upgrades','User'].filter(category=>Object.values(vpModifiers(v,category)).some(Boolean)).map(category=>[category,vpModifiers(v,category)]),...(Object.values(pending).some(Boolean)?[['Pending',pending]]:[]),['Total',current]];return `<div class="table-wrap"><table class="vp-stat-table"><thead><tr><th>Type</th>${vpStatFields.map(([,label])=>`<th>${label}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,values])=>`<tr><th>${label}</th>${vpStatFields.map(([key])=>`<td>${values[key]??'—'}${['Base','Total'].includes(label)?key==='movement'?'″':['handling','save'].includes(key)?'+':'':''}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
